import requests
base='https://www.ebi.ac.uk/europepmc/webservices/rest/search'
queries=['TITLE_ABS:(proatrial natriuretic peptide) AND TITLE_ABS:(obesity OR obese) AND TITLE_ABS:(blood pressure)','TITLE_ABS:(proANP OR "pro-ANP" OR "N-terminal proatrial natriuretic peptide") AND TITLE_ABS:(obese OR obesity OR adiposity)']
for q in queries:
 r=requests.get(base,params={'query':q,'format':'json','pageSize':20,'resultType':'core'},timeout=20)
 print('\nQUERY',q,'COUNT',r.json().get('hitCount'))
 for x in r.json().get('resultList',{}).get('result',[]):
  print(x.get('pmid'),x.get('title'),x.get('authorString'),x.get('journalTitle'),x.get('pubYear'))
  ab=x.get('abstractText','')
  if ab: print(ab[:1800].replace('<p>',' ').replace('</p>',' '))
